/** Hand-calculated fixtures; no expected values are generated by the implementation. */
// Pinned oracle: https://github.com/vega/vega/tree/v6.4.0
// Exponentials: packages/vega-transforms/src/util/AggregateOps.js (not vega-statistics).
// Windows: packages/vega-transforms/src/util/WindowOps.js; dates: packages/vega-time/src/floor.js.
export const statisticsRows = [2, 4, 6, 8, null, undefined, '', NaN].map(value => ({ value }));

// For [2,4,6,8]: mean=5, squared deviations=20, sample variance=20/3.
export const statisticsExpectations: Array<[string, unknown]> = [
  ['count', 8],
  ['valid', 4],
  ['missing', 3],
  ['sum', 20],
  ['product', 384],
  ['mean', 5],
  ['average', 5],
  ['median', 5],
  ['q1', 3.5],
  ['q3', 6.5],
  ['min', 2],
  ['max', 8],
  ['variance', 20 / 3],
  ['variancep', 5],
  ['stdev', Math.sqrt(20 / 3)],
  ['stdevp', Math.sqrt(5)],
  ['stderr', Math.sqrt(5 / 3)],
];

