// Vega v6.4.0 Bin: [0,10], step=2; final bin is right-closed, outliers propagate infinities.
export const binRows = [-1, 0, 1.999, 2, 9, 10, 11, null, undefined, '', NaN].map(v => ({ v }));
export const binBounds = [
  [-Infinity, -Infinity],
  [0, 2],
  [0, 2],
  [2, 4],
  [8, 10],
  [8, 10],
  [Infinity, Infinity],
  [null, null],
  [null, null],
  [null, null],
  [NaN, NaN],
];

